    { id: 'hotspots', name: 'Hotspots',         type: 'Object', required: false, localized: false, validations: [] },
  ];

  let ct;
  let isNew = false;

  try {
    ct = await client.contentType.get({ environmentId, contentTypeId });
  } catch (err) {
    if (err.name !== 'NotFound') throw err;
    isNew = true;
  }

  if (isNew) {
    ct = await client.contentType.createWithId(
      { environmentId, contentTypeId },
      {
        name: 'Shoppable Image',
        displayField: 'title',
        description: 'An editorial image with product hotspots. Each hotspot links to an SFCC product.',
        fields,
      },
    );
  } else {
    // Merge: preserve any fields not in this definition, update the ones that are
    const definedIds = new Set(fields.map((f) => f.id));
    ct.fields = [
      ...(ct.fields ?? []).filter((f) => !definedIds.has(f.id)),
      ...fields,
    ];
    ct.displayField = 'title';
    ct = await client.contentType.update({ environmentId, contentTypeId }, ct);
  }

  await client.contentType.publish({ environmentId, contentTypeId }, ct);
}
